package anki

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"os"
	"sort"
	"strings"

	"github.com/glebarez/sqlite"
	"gorm.io/gorm"
	"gorm.io/gorm/logger"
)

// openCollection opens the SQLite payload the reader already streamed into a
// temporary file. The file name is generated by the operating system, never
// taken from an archive entry, so a hostile entry name cannot choose a path
// outside the temporary directory. The cleanup function closes the database
// and removes the file; it must be called on every path.
func openCollection(path string) (*gorm.DB, func(), error) {
	cleanup := func() { os.Remove(path) }
	db, err := gorm.Open(sqlite.Open(path), &gorm.Config{
		Logger: logger.Default.LogMode(logger.Silent),
	})
	if err != nil {
		cleanup()
		return nil, nil, fmt.Errorf("%w: open sqlite: %v", ErrCorruptCollection, err)
	}
	sqlDB, err := db.DB()
	if err != nil {
		cleanup()
		return nil, nil, fmt.Errorf("%w: open sqlite: %v", ErrCorruptCollection, err)
	}
	cleanup = func() {
		sqlDB.Close()
		os.Remove(path)
	}
	if err := sqlDB.Ping(); err != nil {
		cleanup()
		return nil, nil, fmt.Errorf("%w: open sqlite: %v", ErrCorruptCollection, err)
	}
	return db, cleanup, nil
}

// readLegacyCollection decodes a schema-11 collection: note types and decks
// are JSON columns of the col table, notes and cards are tables.
func readLegacyCollection(db *gorm.DB, pkg *Package) ([]NoteType, []Deck, []Note, []Card, error) {
	var modelsJSON, decksJSON string
	row := db.Raw("SELECT models, decks FROM col").Row()
	if err := row.Scan(&modelsJSON, &decksJSON); err != nil {
		return nil, nil, nil, nil, fmt.Errorf("%w: col table: %v", ErrCorruptCollection, err)
	}

	var models map[string]legacyModel
	if err := json.Unmarshal([]byte(modelsJSON), &models); err != nil {
		return nil, nil, nil, nil, fmt.Errorf("%w: col.models: %v", ErrCorruptCollection, err)
	}
	noteTypes, err := legacyNoteTypes(models)
	if err != nil {
		return nil, nil, nil, nil, err
	}

	var decks map[string]legacyDeck
	if err := json.Unmarshal([]byte(decksJSON), &decks); err != nil {
		return nil, nil, nil, nil, fmt.Errorf("%w: col.decks: %v", ErrCorruptCollection, err)
	}
	deckList, err := legacyDecks(decks)
	if err != nil {
		return nil, nil, nil, nil, err
	}

	notes, err := readNotes(db)
	if err != nil {
		return nil, nil, nil, nil, err
	}
	cards, err := readCards(db, pkg)
	if err != nil {
		return nil, nil, nil, nil, err
	}
	return noteTypes, deckList, notes, cards, nil
}

// legacyModel is the schema-11 model JSON this reader uses.
type legacyModel struct {
	ID                int64            `json:"id"`
	Name              string           `json:"name"`
	Type              int              `json:"type"`
	SortField         int              `json:"sortf"`
	Fields            []legacyField    `json:"flds"`
	Templates         []legacyTemplate `json:"tmpls"`
	CSS               string           `json:"css"`
	LaTeXPre          string           `json:"latexPre"`
	LaTeXPost         string           `json:"latexPost"`
	LaTeXSVG          bool             `json:"latexsvg"`
	OriginalStockKind int              `json:"originalStockKind"`
	// Engram is the one unknown top-level key engram writes. It survives engram to engram
	// and engram to Anki, but Anki's default modern export stores note types as protobuf,
	// and the reader below does not read the key back from that layout. See write.go's
	// legacyEngramOut comment for the full limitation.
	Engram *legacyEngram `json:"engram"`
}

type legacyEngram struct {
	V           int                   `json:"v"`
	AnswerSpecs map[string]AnswerSpec `json:"answer_specs"`
}

type legacyField struct {
	Ord               int    `json:"ord"`
	Name              string `json:"name"`
	ID                int64  `json:"id"`
	Sticky            bool   `json:"sticky"`
	RTL               bool   `json:"rtl"`
	Font              string `json:"font"`
	Size              int    `json:"size"`
	Description       string `json:"description"`
	PlainText         bool   `json:"plainText"`
	Collapsed         bool   `json:"collapsed"`
	ExcludeFromSearch bool   `json:"excludeFromSearch"`
	Tag               *int   `json:"tag"`
	PreventDeletion   bool   `json:"preventDeletion"`
}

type legacyTemplate struct {
	Ord      int    `json:"ord"`
	Name     string `json:"name"`
	ID       int64  `json:"id"`
	QFormat  string `json:"qfmt"`
	AFormat  string `json:"afmt"`
	BQFormat string `json:"bqfmt"`
	BAFormat string `json:"bafmt"`
	BFont    string `json:"bfont"`
	BSize    int    `json:"bsize"`
	Did      *int64 `json:"did"`
}

type legacyDeck struct {
	ID   int64  `json:"id"`
	Name string `json:"name"`
	Desc string `json:"desc"`
	Conf int64  `json:"conf"`
}

func legacyNoteTypes(models map[string]legacyModel) ([]NoteType, error) {
	ids := make([]int64, 0, len(models))
	byID := make(map[int64]legacyModel, len(models))
	for _, model := range models {
		ids = append(ids, model.ID)
		byID[model.ID] = model
	}
	sort.Slice(ids, func(i, j int) bool { return ids[i] < ids[j] })
	noteTypes := make([]NoteType, 0, len(ids))
	for _, id := range ids {
		model := byID[id]
		if model.Type != KindNormal && model.Type != KindCloze {
			return nil, fmt.Errorf("%w: note type %q has unknown kind %d", ErrCorruptCollection, model.Name, model.Type)
		}
		fields := make([]Field, 0, len(model.Fields))
		for _, f := range model.Fields {
			fields = append(fields, Field{
				Ord:               f.Ord,
				Name:              f.Name,
				ID:                f.ID,
				Sticky:            f.Sticky,
				RTL:               f.RTL,
				Font:              f.Font,
				FontSize:          f.Size,
				Description:       f.Description,
				PlainText:         f.PlainText,
				Collapsed:         f.Collapsed,
				ExcludeFromSearch: f.ExcludeFromSearch,
				Tag:               f.Tag,
				PreventDeletion:   f.PreventDeletion,
			})
		}
		sortFields(fields)
		templates := make([]Template, 0, len(model.Templates))
		for _, t := range model.Templates {
			template := Template{
				Ord:             t.Ord,
				Name:            t.Name,
				ID:              t.ID,
				QFormat:         t.QFormat,
				AFormat:         t.AFormat,
				BQFormat:        t.BQFormat,
				BAFormat:        t.BAFormat,
				BrowserFont:     t.BFont,
				BrowserFontSize: t.BSize,
			}
			if t.Did != nil {
				template.TargetDeckID = *t.Did
			}
			templates = append(templates, template)
		}
		sortTemplates(templates)
		var answers map[string]AnswerSpec
		hasAnswerSpecsKey := model.Engram != nil && model.Engram.V == 1
		if hasAnswerSpecsKey {
			answers = model.Engram.AnswerSpecs
		}
		noteTypes = append(noteTypes, NoteType{
			ID:                model.ID,
			Name:              model.Name,
			Kind:              model.Type,
			SortFieldIndex:    model.SortField,
			Fields:            fields,
			Templates:         templates,
			CSS:               model.CSS,
			LaTeXPre:          model.LaTeXPre,
			LaTeXPost:         model.LaTeXPost,
			LaTeXSVG:          model.LaTeXSVG,
			OriginalID:        model.ID,
			OriginalStockKind: model.OriginalStockKind,
			AnswerSpecs:       answers,
			AnswerSpecsKey:    hasAnswerSpecsKey,
		})
	}
	return noteTypes, nil
}

func legacyDecks(decks map[string]legacyDeck) ([]Deck, error) {
	ids := make([]int64, 0, len(decks))
	byID := make(map[int64]legacyDeck, len(decks))
	for _, deck := range decks {
		ids = append(ids, deck.ID)
		byID[deck.ID] = deck
	}
	sort.Slice(ids, func(i, j int) bool { return ids[i] < ids[j] })
	out := make([]Deck, 0, len(ids))
	for _, id := range ids {
		deck := byID[id]
		out = append(out, Deck{ID: deck.ID, Name: deck.Name, Description: deck.Desc, ConfigID: deck.Conf})
	}
	return out, nil
}

// readNotes reads the notes table. Schema 11 and schema 18 use the same
// columns, so both layouts share this query.
func readNotes(db *gorm.DB) ([]Note, error) {
	rows, err := db.Raw("SELECT id, guid, mid, mod, tags, flds FROM notes ORDER BY id").Rows()
	if err != nil {
		return nil, fmt.Errorf("%w: notes table: %v", ErrCorruptCollection, err)
	}
	defer rows.Close()
	var notes []Note
	for rows.Next() {
		var (
			note    Note
			tags    string
			fieldCS string
		)
		if err := rows.Scan(&note.ID, &note.GUID, &note.NoteTypeID, &note.Modified, &tags, &fieldCS); err != nil {
			return nil, fmt.Errorf("%w: notes table: %v", ErrCorruptCollection, err)
		}
		note.Tags = splitTags(tags)
		note.Fields = splitFields(fieldCS)
		notes = append(notes, note)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("%w: notes table: %v", ErrCorruptCollection, err)
	}
	return notes, nil
}

// readCards reads the cards table. Schema 11 and schema 18 use the same
// columns, so both layouts share this query. A REAL value in cards.nid, cards.did
// or cards.ord fails the import because rounding would invent a reference or
// ordinal. A REAL value in cards.type, cards.queue, cards.odid or cards.flags
// skips and counts the row because its scheduling fields are ambiguous.
func readCards(db *gorm.DB, pkg *Package) ([]Card, error) {
	rows, err := db.Raw("SELECT id, " + rejectRealIntegers("nid", "did", "ord") + ", " + roundedIntegers("mod", "usn", "due", "ivl", "factor", "reps", "lapses", "left", "odue") + ", data, type, queue, odid, flags, typeof(nid), typeof(did), typeof(ord), typeof(type), typeof(queue), typeof(odid), typeof(flags) FROM cards ORDER BY id").Rows()
	if err != nil {
		return nil, fmt.Errorf("%w: cards table: %v", ErrCorruptCollection, err)
	}
	defer rows.Close()
	var cards []Card
	for rows.Next() {
		var card Card
		var rawType, rawQueue, rawOdid, rawFlags any
		var nidType, didType, ordType, typeType, queueType, odidType, flagsType string
		if err := rows.Scan(&card.ID, &card.NoteID, &card.DeckID, &card.Ordinal, &card.Modified, &card.USN, &card.Due, &card.Interval, &card.Factor, &card.Reps, &card.Lapses, &card.Left, &card.OriginalDue, &card.Data, &rawType, &rawQueue, &rawOdid, &rawFlags, &nidType, &didType, &ordType, &typeType, &queueType, &odidType, &flagsType); err != nil {
			return nil, fmt.Errorf("%w: cards table: %v", ErrCorruptCollection, err)
		}
		for i, kind := range []string{nidType, didType, ordType} {
			if kind == "real" {
				return nil, fmt.Errorf("%w: cards.%s holds a REAL value", ErrCorruptCollection, []string{"nid", "did", "ord"}[i])
			}
		}
		if typeType == "real" || queueType == "real" || odidType == "real" || flagsType == "real" {
			// A card with ambiguous scheduling fields cannot be imported, nor can its review rows.
			pkg.CardsSkipped++
			if pkg.SkippedCardIDs == nil {
				pkg.SkippedCardIDs = make(map[int64]bool)
			}
			pkg.SkippedCardIDs[card.ID] = true
			continue
		}
		var typ, queue, odid, flags sql.NullInt64
		for i, value := range []any{rawType, rawQueue, rawOdid, rawFlags} {
			column := []string{"type", "queue", "odid", "flags"}[i]
			dest := []*sql.NullInt64{&typ, &queue, &odid, &flags}[i]
			if err := dest.Scan(value); err != nil {
				return nil, fmt.Errorf("%w: cards.%s: %v", ErrCorruptCollection, column, err)
			}
			if !dest.Valid {
				return nil, fmt.Errorf("%w: cards.%s: NULL value", ErrCorruptCollection, column)
			}
		}
		card.Type, card.Queue, card.OriginalDeckID, card.Flags = int(typ.Int64), int(queue.Int64), odid.Int64, int(flags.Int64)
		cards = append(cards, card)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("%w: cards table: %v", ErrCorruptCollection, err)
	}
	return cards, nil
}

// rejectRealIntegers substitutes a placeholder for REAL values so callers can
// refuse them: rounding an identifier or code would invent a reference, a
// rating or a state.
func rejectRealIntegers(columns ...string) string {
	expressions := make([]string, len(columns))
	for i, column := range columns {
		expressions[i] = fmt.Sprintf("CASE WHEN typeof(%[1]s) = 'real' THEN 0 ELSE %[1]s END", column)
	}
	return strings.Join(expressions, ", ")
}

// roundedIntegers rounds REAL values in integer columns: Anki collections can contain
// them, and otherwise one such value would reject a package whose content is readable.
// Integers stay exact and invalid values remain available for Scan to reject.
func roundedIntegers(columns ...string) string {
	expressions := make([]string, len(columns))
	for i, column := range columns {
		expressions[i] = fmt.Sprintf("CASE WHEN typeof(%[1]s) = 'real' THEN CAST(ROUND(%[1]s) AS INTEGER) ELSE %[1]s END", column)
	}
	return strings.Join(expressions, ", ")
}

// readModernCollection decodes a schema-18 collection. Note types, fields,
// templates and decks are tables; the col table's JSON columns are empty and
// are not read.
func readModernCollection(db *gorm.DB, pkg *Package) ([]NoteType, []Deck, []Note, []Card, error) {
	var ver int
	if err := db.Raw("SELECT ver FROM col").Row().Scan(&ver); err != nil {
		return nil, nil, nil, nil, fmt.Errorf("%w: col table: %v", ErrCorruptCollection, err)
	}
	if ver < 18 {
		return nil, nil, nil, nil, fmt.Errorf("%w: schema version %d is not a modern collection", ErrCorruptCollection, ver)
	}
	noteTypes, err := modernNoteTypes(db)
	if err != nil {
		return nil, nil, nil, nil, err
	}
	decks, err := modernDecks(db)
	if err != nil {
		return nil, nil, nil, nil, err
	}
	notes, err := readNotes(db)
	if err != nil {
		return nil, nil, nil, nil, err
	}
	cards, err := readCards(db, pkg)
	if err != nil {
		return nil, nil, nil, nil, err
	}
	return noteTypes, decks, notes, cards, nil
}

func modernNoteTypes(db *gorm.DB) ([]NoteType, error) {
	fieldsByNT, err := modernFields(db)
	if err != nil {
		return nil, err
	}
	templatesByNT, err := modernTemplates(db)
	if err != nil {
		return nil, err
	}

	rows, err := db.Raw("SELECT id, name, config FROM notetypes ORDER BY id").Rows()
	if err != nil {
		return nil, fmt.Errorf("%w: notetypes table: %v", ErrCorruptCollection, err)
	}
	defer rows.Close()
	var noteTypes []NoteType
	for rows.Next() {
		var (
			id     int64
			name   string
			config []byte
		)
		if err := rows.Scan(&id, &name, &config); err != nil {
			return nil, fmt.Errorf("%w: notetypes table: %v", ErrCorruptCollection, err)
		}
		cfg, err := decodeNoteTypeConfig(config)
		if err != nil {
			return nil, fmt.Errorf("%w: note type %q config: %v", ErrCorruptCollection, name, err)
		}
		if cfg.Kind != KindNormal && cfg.Kind != KindCloze {
			return nil, fmt.Errorf("%w: note type %q has unknown kind %d", ErrCorruptCollection, name, cfg.Kind)
		}
		originalID := id
		if cfg.HasOriginalID {
			originalID = cfg.OriginalID
		}
		noteTypes = append(noteTypes, NoteType{
			ID:                id,
			Name:              name,
			Kind:              cfg.Kind,
			SortFieldIndex:    cfg.SortFieldIndex,
			Fields:            fieldsByNT[id],
			Templates:         templatesByNT[id],
			CSS:               cfg.CSS,
			LaTeXPre:          cfg.LaTeXPre,
			LaTeXPost:         cfg.LaTeXPost,
			LaTeXSVG:          cfg.LaTeXSVG,
			OriginalID:        originalID,
			OriginalStockKind: cfg.OriginalStockKind,
		})
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("%w: notetypes table: %v", ErrCorruptCollection, err)
	}
	return noteTypes, nil
}

func modernFields(db *gorm.DB) (map[int64][]Field, error) {
	rows, err := db.Raw("SELECT ntid, ord, name, config FROM fields ORDER BY ntid, ord").Rows()
	if err != nil {
		return nil, fmt.Errorf("%w: fields table: %v", ErrCorruptCollection, err)
	}
	defer rows.Close()
	out := make(map[int64][]Field)
	for rows.Next() {
		var (
			ntid   int64
			ord    int
			name   string
			config []byte
		)
		if err := rows.Scan(&ntid, &ord, &name, &config); err != nil {
			return nil, fmt.Errorf("%w: fields table: %v", ErrCorruptCollection, err)
		}
		cfg, err := decodeFieldConfig(config)
		if err != nil {
			return nil, fmt.Errorf("%w: field %q config: %v", ErrCorruptCollection, name, err)
		}
		field := Field{
			Ord:               ord,
			Name:              name,
			ID:                cfg.ID,
			Sticky:            cfg.Sticky,
			RTL:               cfg.RTL,
			Font:              cfg.Font,
			FontSize:          cfg.FontSize,
			Description:       cfg.Description,
			PlainText:         cfg.PlainText,
			Collapsed:         cfg.Collapsed,
			ExcludeFromSearch: cfg.ExcludeFromSearch,
			PreventDeletion:   cfg.PreventDeletion,
		}
		if cfg.HasTag {
			tag := cfg.Tag
			field.Tag = &tag
		}
		out[ntid] = append(out[ntid], field)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("%w: fields table: %v", ErrCorruptCollection, err)
	}
	return out, nil
}

func modernTemplates(db *gorm.DB) (map[int64][]Template, error) {
	rows, err := db.Raw("SELECT ntid, ord, name, config FROM templates ORDER BY ntid, ord").Rows()
	if err != nil {
		return nil, fmt.Errorf("%w: templates table: %v", ErrCorruptCollection, err)
	}
	defer rows.Close()
	out := make(map[int64][]Template)
	for rows.Next() {
		var (
			ntid   int64
			ord    int
			name   string
			config []byte
		)
		if err := rows.Scan(&ntid, &ord, &name, &config); err != nil {
			return nil, fmt.Errorf("%w: templates table: %v", ErrCorruptCollection, err)
		}
		cfg, err := decodeTemplateConfig(config)
		if err != nil {
			return nil, fmt.Errorf("%w: template %q config: %v", ErrCorruptCollection, name, err)
		}
		out[ntid] = append(out[ntid], Template{
			Ord:             ord,
			Name:            name,
			ID:              cfg.ID,
			QFormat:         cfg.QFormat,
			AFormat:         cfg.AFormat,
			BQFormat:        cfg.BQFormat,
			BAFormat:        cfg.BAFormat,
			BrowserFont:     cfg.BrowserFont,
			BrowserFontSize: cfg.BrowserFontSize,
			TargetDeckID:    cfg.TargetDeckID,
		})
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("%w: templates table: %v", ErrCorruptCollection, err)
	}
	return out, nil
}

func modernDecks(db *gorm.DB) ([]Deck, error) {
	rows, err := db.Raw("SELECT id, name, kind FROM decks ORDER BY id").Rows()
	if err != nil {
		return nil, fmt.Errorf("%w: decks table: %v", ErrCorruptCollection, err)
	}
	defer rows.Close()
	var decks []Deck
	for rows.Next() {
		var (
			id   int64
			name string
			kind []byte
		)
		if err := rows.Scan(&id, &name, &kind); err != nil {
			return nil, fmt.Errorf("%w: decks table: %v", ErrCorruptCollection, err)
		}
		cfg, err := decodeDeckKind(kind)
		if err != nil {
			return nil, fmt.Errorf("%w: deck %q config: %v", ErrCorruptCollection, name, err)
		}
		decks = append(decks, Deck{
			ID: id,
			// The modern schema joins subdeck components with the ASCII unit
			// separator, while the legacy layouts and every consumer use "::".
			// Exposing the raw byte would make the same deck tree look
			// different depending on the package layout.
			Name:                strings.ReplaceAll(name, "\x1f", "::"),
			Description:         cfg.Description,
			MarkdownDescription: cfg.MarkdownDescription,
			ConfigID:            cfg.ConfigID,
		})
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("%w: decks table: %v", ErrCorruptCollection, err)
	}
	return decks, nil
}

// splitFields splits Anki's field values, which are joined by the ASCII unit
// separator. An empty value still yields one empty field.
func splitFields(flds string) []string {
	return strings.Split(flds, "\x1f")
}

// splitTags drops the leading and trailing spaces schema 11 wraps around the
// tag list and returns the tags in their stored order.
func splitTags(tags string) []string {
	return strings.Fields(tags)
}

func sortFields(fields []Field) {
	sort.SliceStable(fields, func(i, j int) bool { return fields[i].Ord < fields[j].Ord })
}

func sortTemplates(templates []Template) {
	sort.SliceStable(templates, func(i, j int) bool { return templates[i].Ord < templates[j].Ord })
}
